import{_ as s,H as a,f as p,i as t}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"03-高级属性：应对生产级别的应用，你需要掌握哪些技能？","description":"","frontmatter":{},"headers":[{"level":2,"title":"如何提取公共的服务能力？","slug":"如何提取公共的服务能力","link":"#如何提取公共的服务能力","children":[]},{"level":2,"title":"如何快速地开发和交付？","slug":"如何快速地开发和交付","link":"#如何快速地开发和交付","children":[]},{"level":2,"title":"如何优雅地切换流量？","slug":"如何优雅地切换流量","link":"#如何优雅地切换流量","children":[]},{"level":2,"title":"如何削峰和容灾？","slug":"如何削峰和容灾","link":"#如何削峰和容灾","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Serverless进阶实战课/03-高级属性：应对生产级别的应用，你需要掌握哪些技能？.md","filePath":"Serverless进阶实战课/03-高级属性：应对生产级别的应用，你需要掌握哪些技能？.md","lastUpdated":1795535054000}'),n={name:"Serverless进阶实战课/03-高级属性：应对生产级别的应用，你需要掌握哪些技能？.md"};function i(l,e,r,o,E,h){return a(),p("div",null,[...e[0]||(e[0]=[t(`<h1 id="_03-高级属性-应对生产级别的应用-你需要掌握哪些技能" tabindex="-1">03-高级属性：应对生产级别的应用，你需要掌握哪些技能？ <a class="header-anchor" href="#_03-高级属性-应对生产级别的应用-你需要掌握哪些技能" aria-label="Permalink to &quot;03-高级属性：应对生产级别的应用，你需要掌握哪些技能？&quot;">​</a></h1><p>你好，我是静远。</p><p>通过前面的学习，我们已经掌握了函数计算的基本特性和操作流程，可以通过配置触发器的形式来完成一些较为简单的 Serverless 业务场景的开发和运维了。</p><p>但是，针对复杂的场景或者是要上生产环境的应用服务，这样的操作肯定是不够的。就拿我们比较熟悉的微服务来说，一个服务模块从开发到上线运行，需要注意公共代码的复用、开发框架的灵活性、上线时候的灰度发布、线上运维的容灾，针对上下游还需要考虑到如何应对流量的波峰波谷等因素。</p><p>那么，在 Serverless 的函数计算中就不要注意这些了么？Serverless 虽然是无服务器化的，但如果要用好函数计算平台，或者是自己要开发一个 FaaS 化的 Serverless 平台，都应该对这些因素有一个比较清晰的认识，才能更好地驾驭 Serverless。</p><p>今天这节课，我们就按照一个应用“开发 - 发布 - 运维”的顺序，以我们熟知的微服务流程为参照，看看函数计算中，你需要了解哪些高阶的技能。我们先从应用的开发阶段说起。</p><h2 id="如何提取公共的服务能力" tabindex="-1">如何提取公共的服务能力？ <a class="header-anchor" href="#如何提取公共的服务能力" aria-label="Permalink to &quot;如何提取公共的服务能力？&quot;">​</a></h2><p>开发微服务的时候，如果是一个复杂一点的功能，则需要多人协作或者复用一些别人开发好的类库。那么，函数计算中是否也有类似的特性呢？</p><p>层的提出就是为了解决这个问题。你可以将函数依赖的公共库提炼到层，以减少部署、更新时的代码包体积。</p><p>目前，大部分的云厂商都支持各种语言的层，如 Java、Python、Node.js、PHP 等。对于支持层功能的运行时，函数计算会将特定的目录（如 /opt）添加到运行时语言的依赖包搜索路径中。你可以自定义层或者使用云厂商开发好的公共层，这些公共层包含了一些常用的依赖包。</p><p>对于自定义的层，你通常需要将所有内容打包到一个 ZIP 文件包中，并上传到函数计算平台。函数计算运行时会将层的内容解压并部署在特定的目录，如 /opt 目录下。</p><p>使用了层的功能之后，有这样 3 个好处：</p><ul><li><p>函数程序包更小，只关注核心代码，使开发变得更加轻松方便；</p></li><li><p>使用层也可以避免在制作函数 zip 包和依赖项过程中出现未知的错误；</p></li><li><p>由于可以在多个函数中引入使用，可以减少不必要的存储资源浪费。</p></li></ul><p>当然，不同云厂商构建层的方式也不同，我们以百度智能云为例，一起尝试构建一个 Node.js语言运行时的层。</p><p>首先，我们新建一个目录，如 mkdir my_nodejs_layer，并在该目录下新建名为“nodejs”的目录，目录结果如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>➜ my_nodejs_layer tree</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>└── nodejs</span></span>
<span class="line"><span>1 directory, 0 files</span></span></code></pre></div><p>下面，假设我们的函数代码中，需要用到 JavaScript 实用工具库 Lodash，我们将 Lodash 打包到自定义的层中。进入 nodejs 目录，执行 npm install lodash ，我们再来查看一下目录结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>➜ my_nodejs_layer tree -d</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>└── nodejs</span></span>
<span class="line"><span>   └── node_modules</span></span>
<span class="line"><span>       └── lodash</span></span>
<span class="line"><span>           └── fp</span></span>
<span class="line"><span>4 directories</span></span></code></pre></div><p>最后，在 my_nodejs_layer 目录中将 nodejs 打包：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zip -r  nodejs_layer_lodash.zip  nodejs</span></span></code></pre></div><p>这样，我们自定义层的依赖就打好了。我们来看一下层上传之后的运作逻辑：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/1.png" alt=""></a></p><p>我们上传层之后，函数计算会将层的 ZIP 包上传到对象存储。当调用函数执行时，会从对象存储中下载层的 ZIP 包并解压到 /opt 目录。你只需要在代码中访问 /opt 目录，即可读取层的依赖和公共代码。</p><p>当我们上传多个层的时候，一定要注意次序问题，后序的层会覆盖相同目录下的文件。</p><p>到这里，我们已经构建并上传了自己的层，之后，就可以在编写函数的时候，通过约定的路径使用了。是不是非常方便？它其实有点类似我们微服务的依赖包，通常来说，也会通过上传自定义的类库到仓库中，让后续开发的同学更加方便地使用。</p><h2 id="如何快速地开发和交付" tabindex="-1">如何快速地开发和交付？ <a class="header-anchor" href="#如何快速地开发和交付" aria-label="Permalink to &quot;如何快速地开发和交付？&quot;">​</a></h2><p>层确实可以解决我们公共代码逻辑和工具库的使用问题。不过，你可能还很好奇，“在微服务的开发中，可以比较灵活地使用某种自己擅长的语言和框架来开发代码，只要遵循服务之间的接口协议规范，就可以开发出一个模块，来提供服务能力。那么，Serverless 的函数计算是否也有类似的能力，让我可以快速灵活地搞定一个服务并且执行呢？”</p><p>答案是肯定的。为了让更多开发者能够快速灵活地开发自己的服务，除了你熟知的基于函数平台提供的标准运行时来开发函数体之外，函数计算平台通常还会支持用户以自定义镜像的方式上传应用来运行。</p><p>我们以阿里云自定义镜像为例来说明其工作原理。函数计算系统初始化执行环境实例前，会扮演该函数的服务角色，获得临时用户名和密码并拉取镜像。拉取成功后，会根据指定的启动命令、参数以及端口，启动你定义的 HTTP Server。然后这个 HTTP Server 就会接管函数计算系统所有请求的调用。</p><p>在开发函数具体的逻辑之前，我们一般还需要确认开发的是事件函数还是 HTTP 函数，通常来说，平台服务后端对这两种调用方式实现的逻辑不一样。</p><p>下面我们来具体看一下自定义镜像的构建和使用过程，包括五个步骤。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/2.png" alt=""></a></p><p>第一，在创建函数之前，我们需要基于自身业务来实现一个 HTTP Server，并且将其打包成镜像，上传到镜像仓库，供函数计算使用。</p><p>各个云厂商的实现方式不同，主要体现在请求和响应接口上的协议适配以及服务运行方式上。针对 HTTP Server 的实现，这里需要强调 4 个点：</p><ol><li><p>建议基于 HTTP 和事件的触发方式，实现相应的接口功能；</p></li><li><p>需要根据接口协议规范，实现请求 Header 和 Body 中值的解析和处理；</p></li><li><p>上传镜像时，需要指定容器的启动命令 Command、参数 Args 及监听端口 Port；</p></li><li><p>推荐实现一个 Healthz 函数，用于健康监测。</p></li></ol><p>第二，我们来创建一个函数，此时，就只需要设置函数运行相关的一些基本属性，如运行超时时间、内存大小、并发度等，再关联第一步中构建的镜像即可。</p><p>第三，根据我们自身的业务场景，选择合适的触发方式来请求函数计算平台，比如，我们可以通过创建和设置一个 HTTP 触发器来链接事件源。</p><p>第四，通过ＨTTP 触发器进行请求。由于自定义镜像是 HTTP Server 的形式存在，我们通常会设定监听的 IP、端口（如 0.0.0.0:9000）、超时时间、HTTP 参数（如 Keep-alive）等。这里需要说明一下，如果是首次启动，函数计算平台会从镜像仓库拉取自定义的镜像，并启动容器。</p><p>最后，函数计算服务控制器会将接收到的请求，调度到对应的 HTTP Server，由 HTTPServer 接管后续的服务处理。</p><p>这样，我们就通过自定义镜像的功能，达到了快速开发和交付的能力，对于老的服务改造迁移，成本也非常低了。</p><h2 id="如何优雅地切换流量" tabindex="-1">如何优雅地切换流量？ <a class="header-anchor" href="#如何优雅地切换流量" aria-label="Permalink to &quot;如何优雅地切换流量？&quot;">​</a></h2><p>我经常会被客户问到，我们的函数功能开发完成后，如何灰度发布，怎么保证我的流量无损切换，如何让我小流量实验后再全面转正呢？这可能是刚接触 FaaS 的通用问题了。接下来，我们可以看看函数计算的流量是如何做到优雅切换的。</p><p>这里引出两个概念：版本和别名，函数计算支持为发布的函数版本创建别名。别名可以理解为指向特定版本的一个指针。你可以利用别名来轻松实现流量切换、版本回滚以及灰度发布等功能。下面这个示意图，可以很好地说明这个运行机制。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/3.png" alt=""></a></p><p>以 HTTP 触发器为例，如果没有别名，每次新版本上线，你都需要手动修改 HTTP 触发器关联的版本号。如上图所示。</p><p>在实际业务开发中，一般会基于最新版本 $LATEST 的代码来开发。针对开发好的函数，你可以发布一个版本出来，比如 Public Version1，函数计算平台会记录发布的版本信息，通过配置一个别名指向该版本，就可以用来处理对外的请求了。</p><p>而且，你还可以在 $LATEST 版本上继续开发。同样，开发完成之后，只需要再次发布新的版本 Public Version2 即可。</p><p>如果此时，我们需要将流量切换到新发布的版本上，只需要切换别名的指向即可，而用户在这个过程是无感知的，也不会有任何的流量损失。</p><p>如果我们对新的功能版本不是那么放心，还可以设置主版本和新版本的流量比例。比如我们设置 95% 的流量指向主版本，5% 的指向最新版本。观察没问题后，再全流量切换到新版本。如果出现问题，需要进行回滚，只需将指针指向原来的版本或者关闭新版本的测试流量即可。</p><p>这样就可以优雅地完成版本的迭代升级了。别名无法脱离服务或版本单独存在，使用别名访问服务或函数时，函数计算会将别名解析为其指向的版本，调用方无需了解别名指向的具体版本。有了版本控制和别名，我们就可以在线上服务不受影响的基础上，完成优雅的流量变更。</p><h2 id="如何削峰和容灾" tabindex="-1">如何削峰和容灾？ <a class="header-anchor" href="#如何削峰和容灾" aria-label="Permalink to &quot;如何削峰和容灾？&quot;">​</a></h2><p>上线的平滑性问题解决了，那么，函数在运行的时候呢？是否也像微服务那样，考虑到了服务的治理呢？</p><p>这里我们聚焦一下，看看微服场景下老生常谈的流量突增和服务处理异常的情况。这种问题，在 Serverless 领域也同样需要关注。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/4.png" alt=""></a></p><p>微服务中，主要是通过异步消息队列的方式来应对流量峰值，当然，这只是针对延时不敏感的服务场景来说，如日志的 ETL、批量处理、事件处理等。针对这种情况，在函数计算的Serverless 平台中，也往往会通过引入消息队列的方式，先将突增的流量引入进来，然后再通过后端的调度系统调度给云函数处理。</p><p>这样的做法，既可以避免突增流量使得后端资源池来不及扩容，导致出现失败的情况，又让函数计算平台可以快速地响应请求方，避免等待，由函数计算平台来保证请求可靠地执行。</p><p>既然谈到万一资源池扩容没跟上请求速度，或者像公有云这种资源池出现调度问题的情况了，那么我们可以想一想，函数计算平台是否有容灾的能力呢？</p><p>从平台的角度来说，云厂商都是做了同步重试、异步延时重试的逻辑的。针对异步的信息，甚至引入了递增重试机制和异步策略到用户自己的容灾队列、容灾处理函数中去处理，来进一步保障消息的可靠传输和处理。</p><p>那么，平台是怎么做的呢？一般来说，云厂商会选择在函数计算引擎之上增加流量转发和调度层。如果收到函数实例返回错误的信息，通过在调度层用户配置的策略来进行针对性的分发即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/03-%25E9%25AB%2598%25E7%25BA%25A7%25E5%25B1%259E%25E6%2580%25A7/5.png" alt=""></a></p><p>从使用者的角度来看，针对延时不敏感的场景，建议选择异步方式来处理函数的计算，同时配置容灾队列或者云函数的链式调用方法来解决处理异常的情况。</p><p>到这里，我们今天要讲的内容也快进入尾声了。不过，要做到微服务成熟的治理模式，对于Serverless 的函数计算平台和业务来说，都还有比较长的路要走。</p><p>FaaS 作为云原生时代的“连接器”“胶水语言”，在处理复杂场景逻辑的时候，必不可少地要跟其他 VPC 内的服务进行交互，在开发和运维过程中，也需要完善的开发工具链和可观测能力的支撑。后续我也会逐一来展开，跟你介绍其中的实现机制和实战策略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我来小结一下今天的内容。虽然通过前面的小节，你已经可以在一些简单的场景使用函数计算了，但复杂的场景还需要进一步掌握它的一些高级属性，这些属性包括层、自定义镜像、别名和版本、异步策略的使用等。</p><p>函数计算平台，通过提供层的能力，让你能够轻松地封装起公共的代码库和工具依赖库，解决了公共代码复用和依赖的问题；考虑到传统开发者切换的需求，采用自定义镜像的方式，不仅可以提高开发和交付的效率，还能够从一定程度上复用原来的 CICD 系统和老的服务模块，进一步提升人效。</p><p>考虑到我们的服务是需要上生产环境的，别名和版本这一对孪生兄弟，也就正好有了用武之地。其实，在其他的云产品中也有这种用法，比如 Elasticsearch 中的别名也有类似的作用。</p><p>服务的线上运行，少不了容灾降级和应对峰值压力的考量，虽然函数计算具备弹性伸缩的能力，但考虑到资源池的调度速度和未知的错误容灾，作为一名“FaaSer”，你也应该学会将微服务的成熟的经验引入进来，并在函数计算、Serverless 领域发挥起来。</p><p>如果你的工作内容仅限于使用函数计算平台来开发业务代码，那么通过本节课程，你应该对平台的使用和注意事项已经非常熟悉了，对开发一个高可用、高可扩展的函数服务也一定有了较为深入的理解。</p><p>如果你的工作角色是一个云平台开发者，那么，本节课对你步入函数计算领域或者进一步梳理、补充 FaaS 形态的 Serverless 平台的能力，都是一个很好的参考支点。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>好了，这节课到这里也就结束了，最后我给你留了一个思考题。</p><p>函数计算形态下的 Serverless，是如何打造高级的能力来应对长进程的处理场景的？</p><p>欢迎在留言区写下你的思考和答案，我们一起交流讨论。感谢你的阅读，也欢迎你把这节课分享给更多的朋友一起交流进步。</p>`,74)])])}const g=s(n,[["render",i]]);export{d as __pageData,g as default};
